package com.cse309.cache.simulation;

import java.time.Duration;

/**
 * Encapsulates a planned cache operation generated by the simulation generator.
 */
public final class PlannedOperation {

    public enum Type {
        GET,
        PUT,
        UPDATE,
        DELETE,
        SEARCH
    }

    private final Type type;
    private final String key;
    private final String value;
    private final Duration ttl;
    private final int sequence;

    public PlannedOperation(Type type, String key, String value, Duration ttl, int sequence) {
        this.type = type;
        this.key = key;
        this.value = value;
        this.ttl = ttl;
        this.sequence = sequence;
    }

    public Type getType() { return type; }
    public String getKey() { return key; }
    public String getValue() { return value; }
    public Duration getTtl() { return ttl; }
    public int getSequence() { return sequence; }

    @Override
    public String toString() {
        return String.format("#%d %s key='%s'", sequence, type, key);
    }
}
